mapper.select:
SELECT DISTINCT p.*
FROM policy p
         JOIN policy_target_region ptr
              ON p.id = ptr.policy_id
WHERE p.id = #{id}
  AND ptr.sgg_code = #{region}
  AND (
      (p.min_age = 0 AND p.max_age = 0)
      OR (
          p.min_age  <=  #{age}
          AND p.max_age  >=  #{age}
      )
  )

SELECT DISTINCT p.*
FROM policy p
JOIN policy_target_region ptr
ON p.id = ptr.policy_id
WHERE ptr.sgg_code = #{region}
AND (
    (p.min_age = 0 AND p.max_age = 0)
    OR (
        p.min_age  <=  #{age}
        AND p.max_age  >=  #{age}
    )
)


    AND (
    p.title LIKE CONCAT('%', #{keyword}, '%')
    OR p.apply_method LIKE CONCAT('%', #{keyword}, '%')
    OR p.required_documents LIKE CONCAT('%', #{keyword}, '%')
    )


ORDER BY p.id DESC
